/**
 * Centralized input bindings.
 * Change keys here to remap controls globally.
 * Each action maps to an array of accepted key values (KeyboardEvent.key).
 */
const CONTROLS = {
  LEFT: ['ArrowLeft', 'a', 'A'],
  RIGHT: ['ArrowRight', 'd', 'D'],
  JUMP: ['ArrowUp', 'w', 'W', ' '],
  FIRE: ['f', 'F'],
};

export default CONTROLS;
